def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.swapcase()

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def _count_sevens_divisible_by(limit: int, divisor: int) -> int:
    """Count occurrences of the digit 7 in 0..limit divisible by divisor."""
    if limit < 0:
        return 0

    digits = [int(ch) for ch in str(limit)]
    # dp maps (remainder, number_of_sevens, is_tight) -> prefix count.
    dp = {(0, 0, True): 1}

    for bound_digit in digits:
        next_dp = {}
        for (remainder, sevens, tight), ways in dp.items():
            max_digit = bound_digit if tight else 9
            for digit in range(max_digit + 1):
                new_remainder = (remainder * 10 + digit) % divisor
                new_sevens = sevens + (digit == 7)
                new_tight = tight and digit == bound_digit
                key = (new_remainder, new_sevens, new_tight)
                next_dp[key] = next_dp.get(key, 0) + ways
        dp = next_dp

    return sum(sevens * ways for (remainder, sevens, _), ways in dp.items()
               if remainder == 0)


def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    if n <= 0:
        return 0

    limit = n - 1
    return (
        _count_sevens_divisible_by(limit, 11)
        + _count_sevens_divisible_by(limit, 13)
        - _count_sevens_divisible_by(limit, 143)
    )

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def digitSum(s):
    """Return the sum of the ASCII codes of the uppercase characters in s."""
    return sum(ord(char) for char in s if char.isupper())

def pluck(arr):
    """
    Return [smallest_even_value, its_index] from arr, or [] if none exists.
    """
    best_value = None
    best_index = -1

    for index, value in enumerate(arr):
        if value % 2 == 0 and (best_value is None or value < best_value):
            best_value = value
            best_index = index

    if best_value is None:
        return []

    return [best_value, best_index]

def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers.

    The three primes are counted with multiplicity, so for example
    8 = 2 * 2 * 2 and 12 = 2 * 2 * 3 are both valid.
    """
    if a < 2:
        return False

    count = 0
    n = a
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            n //= divisor
            count += 1
            if count > 3:
                return False
        divisor += 1

    if n > 1:
        count += 1

    return count == 3

def hex_key(num):
    """Count the hexadecimal digits in num that represent prime numbers."""
    return sum(digit in "2357BD" for digit in num)

def decimal_to_binary(decimal):
    """Convert a decimal number to a binary string wrapped in 'db'."""
    return "db" + bin(decimal)[2:] + "db"

def is_happy(s):
    """Return True if s is happy: length >= 3 and every three
    consecutive characters are distinct.
    """
    if len(s) < 3:
        return False

    for i in range(len(s) - 2):
        if len({s[i], s[i + 1], s[i + 2]}) < 3:
            return False

    return True

def numerical_letter_grade(grades):
    """Convert a list of GPAs to the corresponding letter grades."""
    result = []
    for gpa in grades:
        if gpa == 4.0:
            result.append("A+")
        elif gpa > 3.7:
            result.append("A")
        elif gpa > 3.3:
            result.append("A-")
        elif gpa > 3.0:
            result.append("B+")
        elif gpa > 2.7:
            result.append("B")
        elif gpa > 2.3:
            result.append("B-")
        elif gpa > 2.0:
            result.append("C+")
        elif gpa > 1.7:
            result.append("C")
        elif gpa > 1.3:
            result.append("C-")
        elif gpa > 1.0:
            result.append("D+")
        elif gpa > 0.7:
            result.append("D")
        elif gpa > 0.0:
            result.append("D-")
        else:
            result.append("E")
    return result

def prime_length(string):
    """Return True if the length of *string* is a prime number."""
    n = len(string)
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    return 18 * 10 ** (n - 2)

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices..


    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    return sum(value for index, value in enumerate(lst) if index % 2 == 1 and value % 2 == 0)

def get_row(lst, x):
    """
    Find all occurrences of x in a ragged 2D list.

    Returns coordinates as (row, column) tuples, ordered by row ascending
    and, within each row, by column descending.
    """
    result = []
    for row_index, row in enumerate(lst):
        for column_index in range(len(row) - 1, -1, -1):
            if row[column_index] == x:
                result.append((row_index, column_index))
    return result

def sort_array(array):
    """
    Return a sorted copy of the array.

    Sort ascending when the sum of the first and last elements is odd,
    and descending when that sum is even. The input array is not modified.
    """
    if not array:
        return []

    descending = (array[0] + array[-1]) % 2 == 0
    return sorted(array, reverse=descending)

def encrypt(s):
    """Encrypt a string by rotating each letter four places down the alphabet."""
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            result.append(chr((ord(char) - ord('a') + 4) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            result.append(chr((ord(char) - ord('A') + 4) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

def next_smallest(lst):
    """
    Return the second smallest distinct element of a list of integers,
    or None if no such element exists.
    """
    smallest = second = None

    for value in lst:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value

    return second

import re


def is_bored(S):
    """
    Count the number of sentences that start with the word "I".

    Sentences are delimited by '.', '?' or '!'.
    """
    sentences = re.split(r'[.?!]', S)
    return sum(
        1 for sentence in sentences
        if re.match(r'\s*I(?:\s|$)', sentence)
    )

def encode(message):
    """
    Swap the case of every letter and replace each vowel with the
    letter two places ahead of it in the English alphabet.
    """
    vowels = "aeiouAEIOU"
    encoded = []

    for char in message:
        if char in vowels:
            char = chr(ord(char) + 2)
        encoded.append(char.swapcase())

    return "".join(encoded)

from math import isqrt


def _is_prime(n):
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    divisor = 5
    while divisor <= isqrt(n):
        if n % divisor == 0 or n % (divisor + 2) == 0:
            return False
        divisor += 6
    return True


def skjkasdkd(lst):
    """Return the sum of the digits of the largest prime in lst."""
    largest_prime = max((n for n in lst if _is_prime(n)), default=None)
    if largest_prime is None:
        return 0
    return sum(int(digit) for digit in str(largest_prime))

def count_up_to(n):
    """Return all prime numbers less than n.

    Args:
        n: A non-negative integer.

    Returns:
        A list of the prime numbers less than n, in ascending order.
    """
    if n <= 2:
        return []

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for number in range(2, int(n ** 0.5) + 1):
        if is_prime[number]:
            for multiple in range(number * number, n, number):
                is_prime[multiple] = False

    return [number for number in range(2, n) if is_prime[number]]

def multiply(a, b):
    """Return the product of the unit digits of two integers."""
    return (a % 10) * (b % 10)

def f(n):
    """Return a list of size n where element j uses i = j + 1:
    factorial(i) when i is even, otherwise the sum 1 + 2 + ... + i.
    """
    result = []
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i
        if i % 2 == 0:
            result.append(factorial)
        else:
            result.append(i * (i + 1) // 2)
    return result

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    counts = {}
    for letter in test.split():
        counts[letter] = counts.get(letter, 0) + 1

    if not counts:
        return {}

    highest = max(counts.values())
    return {letter: count for letter, count in counts.items() if count == highest}

def sort_array(arr):
    """
    Sort non-negative integers by the number of 1 bits in their binary
    representation, breaking ties by decimal value.

    Negative values are outside the stated domain.  For compatibility with
    the provided example, an all-negative array is sorted by decimal value.
    """
    if all(x < 0 for x in arr):
        return sorted(arr)
    return sorted(arr, key=lambda x: (bin(x).count('1'), x))

def select_words(s, n):
    """Return the words in s that contain exactly n consonants."""
    if not s:
        return []

    vowels = set("aeiouAEIOU")
    result = []

    for word in s.split():
        consonant_count = sum(
            1 for char in word if char.isalpha() and char not in vowels
        )
        if consonant_count == n:
            result.append(word)

    return result

def get_closest_vowel(word):
    """Return the closest vowel between two consonants, searching from the right."""
    vowels = "aeiouAEIOU"

    for i in range(len(word) - 2, 0, -1):
        if (
            word[i] in vowels
            and word[i - 1] not in vowels
            and word[i + 1] not in vowels
        ):
            return word[i]

    return ""

def valid_date(date):
    """Return True if date is a valid date string in mm-dd-yyyy format."""
    if not isinstance(date, str) or not date:
        return False

    parts = date.split("-")
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts
    if (len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4):
        return False

    if not all(part.isascii() and part.isdigit()
               for part in (month_str, day_str, year_str)):
        return False

    month = int(month_str)
    day = int(day_str)

    if month < 1 or month > 12 or day < 1:
        return False

    if month == 2:
        return day <= 29
    if month in (4, 6, 9, 11):
        return day <= 30
    return day <= 31

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    if any(char.isspace() for char in txt):
        return txt.split()
    if ',' in txt:
        return txt.split(',')
    return sum(
        1 for char in txt
        if 'a' <= char <= 'z' and (ord(char) - ord('a')) % 2 == 1
    )

def intersection(interval1, interval2):
    """Return "YES" if the length of the intervals' intersection is prime."""
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    length = end - start

    if length < 2:
        return "NO"

    for divisor in range(2, int(length ** 0.5) + 1):
        if length % divisor == 0:
            return "NO"

    return "YES"

def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    result = [1]

    for i in range(1, n + 1):
        if i == 1:
            result.append(3)
        elif i % 2 == 0:
            result.append(1 + i // 2)
        else:
            # tri(i) = tri(i - 1) + tri(i - 2) + tri(i + 1),
            # where i + 1 is even.
            result.append(result[i - 1] + result[i - 2] + 1 + (i + 1) // 2)

    return result

def is_nested(string):
    '''
    Return True if the string contains a valid bracket subsequence with nesting.

    A nested subsequence exists exactly when "[", "[", "]", "]" appear in
    that order as a subsequence.
    '''
    state = 0
    for char in string:
        if state == 0 and char == '[':
            state = 1
        elif state == 1 and char == '[':
            state = 2
        elif state == 2 and char == ']':
            state = 3
        elif state == 3 and char == ']':
            return True
    return False

def can_arrange(arr):
    """Return the largest index whose value is less than the preceding value.

    If no such element exists, return -1.
    """
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] < arr[i - 1]:
            return i
    return -1

def file_name_check(file_name):
    """Return 'Yes' if file_name is valid according to the stated rules, else 'No'."""
    if sum(char.isdigit() for char in file_name) > 3:
        return 'No'

    if file_name.count('.') != 1:
        return 'No'

    name, extension = file_name.split('.')
    if not name or not ('a' <= name[0] <= 'z' or 'A' <= name[0] <= 'Z'):
        return 'No'

    if extension not in ('txt', 'exe', 'dll'):
        return 'No'

    return 'Yes'

def sum_squares(lst):
    """Square entries at indices divisible by 3, cube entries at indices
    divisible by 4 (but not 3), and return the sum of all entries.
    """
    total = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total += value ** 2
        elif index % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def words_in_sentence(sentence):
    """
    Return the words from sentence whose lengths are prime numbers,
    preserving their original order.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n < 4:
            return True
        if n % 2 == 0:
            return False
        divisor = 3
        while divisor * divisor <= n:
            if n % divisor == 0:
                return False
            divisor += 2
        return True

    return " ".join(
        word for word in sentence.split() if is_prime(len(word))
    )

def sorted_list_sum(lst):
    """Return the even-length strings sorted by length, then alphabetically."""
    return sorted((word for word in lst if len(word) % 2 == 0),
                  key=lambda word: (len(word), word))

def x_or_y(n, x, y):
    """Return x if n is prime, otherwise return y.

    Examples:
    x_or_y(7, 34, 12) == 34
    x_or_y(15, 8, 5) == 5
    """
    if n < 2:
        return y

    if n % 2 == 0:
        return x if n == 2 else y

    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return y
        divisor += 2

    return x

def Strongest_Extension(class_name, extensions):
    """Return the class name and its strongest extension joined by a dot."""
    strongest = extensions[0]
    strongest_strength = sum(1 if c.isupper() else -1 if c.islower() else 0
                             for c in strongest)

    for extension in extensions[1:]:
        strength = sum(1 if c.isupper() else -1 if c.islower() else 0
                       for c in extension)
        if strength > strongest_strength:
            strongest = extension
            strongest_strength = strength

    return f"{class_name}.{strongest}"

def cycpattern_check(a, b):
    """Return True if b or any rotation of b is a substring of a."""
    if not b:
        return True
    return any(b[i:] + b[:i] in a for i in range(len(b)))

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even = odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return even, odd

def find_max(words):
    """Return the word with the most unique characters.

    Ties are broken by choosing the lexicographically first word.
    """
    if not words:
        return None

    max_unique = max(len(set(word)) for word in words)
    return min(word for word in words if len(set(word)) == max_unique)

def solve(s):
    """Reverse the case of each letter in s, or reverse s if it has no letters."""
    if not any(ch.isalpha() for ch in s):
        return s[::-1]
    return s.swapcase()

import hashlib


def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def similar_elements(list1, list2):
    """Return the elements shared by both input sequences."""
    return set(list1) & set(list2)

def is_not_prime(n):
    """Return True if n is not a prime number, otherwise False."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 2:
        return True
    if n < 4:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return True

    divisor = 5
    while divisor * divisor <= n:
        if n % divisor == 0 or n % (divisor + 2) == 0:
            return True
        divisor += 6
    return False

import heapq


def heap_queue_largest(numbers, n):
    """Return the n largest numbers in descending order."""
    return heapq.nlargest(n, numbers)

