def remove_dirty_chars(string: str, dirty_chars: str) -> str:
    """Remove all characters in ``dirty_chars`` from ``string``."""
    dirty = set(dirty_chars)
    return "".join(char for char in string if char not in dirty)


if __name__ == "__main__":
    assert remove_dirty_chars("probasscurve", "pros") == "bacuve"
