def is_woodall(n: int) -> bool:
    """Return True if n is a Woodall number (n = k * 2**k - 1 for k >= 1)."""
    if not isinstance(n, int) or n < 1:
        return False

    k = 1
    while True:
        woodall = k * (1 << k) - 1
        if woodall == n:
            return True
        if woodall > n:
            return False
        k += 1

def find_Max_Num(digits):
    """Return the largest number that can be formed from the given digits."""
    return int("".join(str(digit) for digit in sorted(digits, reverse=True)))

def opposite_Signs(x, y):
    """Return True if the two integers have opposite signs."""
    return (x < 0) != (y < 0)

def is_octagonal(n):
    """Return the nth octagonal number."""
    return n * (3 * n - 2)

def smallest_num(numbers):
    """Return the smallest number in a non-empty list."""
    return min(numbers)


if __name__ == "__main__":
    assert smallest_num([10, 20, 1, 45, 99]) == 1
