def max_difference(tuple_list):
    """Return the largest absolute difference within any pair in the list."""
    return max((abs(a - b) for a, b in tuple_list), default=0)

def subject_marks(subjects):
    """Return the list of (subject, mark) tuples sorted by mark."""
    return sorted(subjects, key=lambda item: item[1])

def recursive_list_sum(data):
    """Return the sum of all numbers in a possibly nested list."""
    total = 0
    for item in data:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def pos_count(numbers):
    """Return the number of positive numbers in a list."""
    return sum(1 for number in numbers if number > 0)

def is_Monotonic(array):
    """Return True if the array is monotonic (non-increasing or non-decreasing)."""
    if len(array) <= 1:
        return True

    increasing = decreasing = True

    for i in range(1, len(array)):
        if array[i] > array[i - 1]:
            decreasing = False
        elif array[i] < array[i - 1]:
            increasing = False

        if not increasing and not decreasing:
            return False

    return True

def is_sublist(lst, sublist):
    """Return True if sublist appears as a contiguous slice of lst."""
    n = len(sublist)
    if n == 0:
        return True
    if n > len(lst):
        return False
    return any(lst[i:i + n] == sublist for i in range(len(lst) - n + 1))

def get_equal(tuples):
    """Return True if all tuples have the same length, otherwise False."""
    if not tuples:
        return True
    return all(len(item) == len(tuples[0]) for item in tuples)

def is_samepatterns(colors, patterns):
    """Return True if ``colors`` follows the same pattern as ``patterns``.

    Two sequences have the same pattern when their elements are equal at
    exactly the same positions, i.e. there is a one-to-one correspondence
    between the values in the two sequences.
    """
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        elif pattern in pattern_to_color:
            return False
        else:
            color_to_pattern[color] = pattern
            pattern_to_color[pattern] = color

