def decimal_to_binary(n: int) -> str:
    """Convert a decimal integer to its binary string representation."""
    if n == 0:
        return "0"

    sign = ""
    if n < 0:
        sign = "-"
        n = -n

    digits = []
    while n > 0:
        digits.append(str(n % 2))
        n //= 2

    return sign + "".join(reversed(digits))

def next_smallest_palindrome(num: int) -> int:
    """Return the smallest palindrome strictly greater than ``num``."""
    if num < 0:
        # 0 is the smallest non-negative palindrome greater than any negative.
        return 0

    digits = str(num)
    length = len(digits)
    half_length = (length + 1) // 2

    # Mirror the left half (including the middle digit for odd lengths).
    left = digits[:half_length]
    candidate = left + left[: length // 2][::-1]

    if int(candidate) > num:
        return int(candidate)

    # Otherwise, increment the left half and mirror it again.
    left = str(int(left) + 1)

    if len(left) > half_length:
        # The number grew a digit, e.g. 99 -> 101 or 999 -> 1001.
        return int("1" + "0" * (length - 1) + "1")

    return int(left + left[: length // 2][::-1])

