def search(nums):
    """Return the only element that appears once in a sorted array.

    Every other element appears exactly twice. The array is expected to have
    odd length; an empty array returns None.
    """
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        # Compare pairs starting at an even index.
        if mid % 2 == 1:
            mid -= 1

        if nums[mid] == nums[mid + 1]:
            # The single element is after this complete pair.
            left = mid + 2
        else:
            # The single element is at or before mid.
            right = mid

    return nums[left]

