from math import isqrt


def _proper_divisor_sum(n):
    """Return the sum of the proper divisors of n."""
    if n < 2:
        return 0

    total = 1
    root = isqrt(n)
    for divisor in range(2, root + 1):
        if n % divisor == 0:
            total += divisor
            paired = n // divisor
            if paired != divisor:
                total += paired
    return total


def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 through limit (inclusive)."""
    if limit < 2:
        return 0

    # Sieve the sums of proper divisors for every number up to limit.
    divisor_sums = [0] * (limit + 1)
    for divisor in range(1, limit // 2 + 1):
        for multiple in range(divisor * 2, limit + 1, divisor):
            divisor_sums[multiple] += divisor

    total = 0
    for number in range(2, limit + 1):
        partner = divisor_sums[number]
        if partner == number or partner == 0:
            continue

        if partner <= limit:
            partner_sum = divisor_sums[partner]
        else:
            partner_sum = _proper_divisor_sum(partner)

        if partner_sum == number:
            total += number

    return total

import cmath


def angle_complex(real, imag=None):
    """Return the angle (phase) of a complex number in radians.

    The number may be supplied either as a single complex value or as
    separate real and imaginary parts.
    """
    if imag is None:
        z = complex(real)
    elif isinstance(imag, complex):
        # Also accept calls such as angle_complex(0, 1j), where the
        # imaginary unit is supplied as the second argument.
        z = complex(real) + imag
    else:
        z = complex(real, imag)
    return cmath.phase(z)

