def magic_square_test(matrix):
    """Return True if matrix is a magic square, otherwise False."""
    if not matrix:
        return False

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    target = sum(matrix[0])

    # Every row and column must have the same sum.
    for i in range(n):
        if sum(matrix[i]) != target:
            return False
        if sum(matrix[j][i] for j in range(n)) != target:
            return False

    # Both main diagonals must also have the target sum.
    main_diagonal = sum(matrix[i][i] for i in range(n))
    anti_diagonal = sum(matrix[i][n - 1 - i] for i in range(n))

    return main_diagonal == target and anti_diagonal == target

