def max_sum(arr):
    """Return the maximum sum of a bitonic subsequence of ``arr``.

    A bitonic subsequence first strictly increases and then strictly
    decreases.  A purely increasing or purely decreasing subsequence is
    also considered bitonic.
    """
    n = len(arr)
    if n == 0:
        return 0

    # inc[i]: maximum sum of an increasing subsequence ending at i.
    inc = list(arr)
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i]: maximum sum of a decreasing subsequence starting at i.
    dec = list(arr)
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The peak is counted in both inc and dec, so subtract it once.
    return max(inc[i] + dec[i] - arr[i] for i in range(n))

def lps(s: str) -> int:
    """Return the length of the longest palindromic subsequence in s."""
    n = len(s)
    if n == 0:
        return 0

    # dp[i][j] is the LPS length for the substring s[i:j + 1].
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = 2 if i + 1 > j - 1 else dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]


