def max_sub_array_sum_repeated(arr, n=None, k=None):
    """Return the maximum contiguous subarray sum in arr repeated k times.

    ``n`` is the length of ``arr`` (kept for compatibility with the usual
    signature).  The implementation runs in O(n) time, independent of k.
    """
    if k is None:
        # Allow calling as max_sub_array_sum_repeated(arr, k).
        k = n if n is not None else 1
        n = len(arr)
    if n is None:
        n = len(arr)

    if n <= 0 or k <= 0:
        return 0

    a = list(arr[:n])
    if not a:
        return 0

    def kadane(sequence):
        best = current = sequence[0]
        for value in sequence[1:]:
            current = max(value, current + value)
            best = max(best, current)
        return best

    best_single = kadane(a)
    if k == 1:
        return best_single

    total = sum(a)

    prefix = best_prefix = a[0]
    for value in a[1:]:
        prefix += value
        best_prefix = max(best_prefix, prefix)

    suffix = best_suffix = a[-1]
    for value in reversed(a[:-1]):
        suffix += value
        best_suffix = max(best_suffix, suffix)

    if total > 0:
        # Use a suffix of the first copy, all middle copies, and a prefix
        # of the last copy.
        return max(
            best_single,
            best_suffix + best_prefix + (k - 2) * total,
        )

    # With non-positive total, an optimal subarray spans at most two copies.
    return max(best_single, best_suffix + best_prefix)

