def max_sum_increasing_subseq(arr, n, i, k):
    """Return the maximum sum of an increasing subsequence that uses only
    elements from ``arr[0..i]`` and also includes ``arr[k]`` (where ``k > i``).

    ``n`` is the length of ``arr``.  Indices ``i`` and ``k`` are zero-based.
    """
    # dp[j] is the maximum sum of an increasing subsequence in arr[0..i]
    # that ends at index j.
    dp = [0] * n
    for j in range(i + 1):
        dp[j] = arr[j]
        for p in range(j):
            if arr[p] < arr[j]:
                dp[j] = max(dp[j], dp[p] + arr[j])

    # Any increasing subsequence ending at a prefix element smaller than
    # arr[k] can be extended by arr[k].
    best_prefix = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            best_prefix = max(best_prefix, dp[j])

    return best_prefix + arr[k]

