from functools import lru_cache


def get_max_sum(n: int) -> int:
    """Return the maximum sum obtainable from n using the given recurrence."""
    if n <= 0:
        return 0

    @lru_cache(maxsize=None)
    def max_sum(value: int) -> int:
        if value == 0:
            return 0
        return max(
            value,
            max_sum(value // 2)
            + max_sum(value // 3)
            + max_sum(value // 4)
            + max_sum(value // 5),
        )

    return max_sum(n)

