def prime_num(n: int) -> bool:
    """Return True if n is a prime number, otherwise False."""
    if not isinstance(n, int) or isinstance(n, bool) or n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2

    return True

