def bell_Number(n):
    """Return the nth Bell number (B_0 = 1, B_1 = 1, B_2 = 2, ...)."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Build the Bell triangle. The first entry of each row is the Bell
    # number for that row's index.
    row = [1]
    for _ in range(n):
        next_row = [row[-1]]
        for value in row:
            next_row.append(next_row[-1] + value)
        row = next_row

    return row[0]

