def largest_subset(numbers):
    """Return the size of the largest subset in which every pair is divisible.

    For a pair (a, b), one of the numbers must divide the other.  Sorting by
    absolute value lets us build such a subset with dynamic programming.
    """
    if not numbers:
        return 0

    # Zero is divisible by every non-zero number, so all zeros can always be
    # included.  Signs do not affect divisibility, so use absolute values.
    zero_count = sum(1 for value in numbers if value == 0)
    values = sorted(abs(value) for value in numbers if value != 0)

    if not values:
        return zero_count

    dp = [1] * len(values)
    for i in range(len(values)):
        for j in range(i):
            if values[i] % values[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp) + zero_count

def get_median(arr1, arr2, n):
    """Return the median of two sorted lists of the same size.

    The merged list has ``2 * n`` elements, so its median is the average
    of the two middle elements.  A binary-search partition gives O(log n)
    time without creating the merged list.
    """
    if n == 0:
        return None

    # Keep arr1 as the list we binary-search over.
    if len(arr1) > len(arr2):
        arr1, arr2 = arr2, arr1

    m, k = len(arr1), len(arr2)
    total_left = (m + k + 1) // 2

    low, high = 0, m
    while low <= high:
        cut1 = (low + high) // 2
        cut2 = total_left - cut1

        left1 = arr1[cut1 - 1] if cut1 > 0 else float("-inf")
        right1 = arr1[cut1] if cut1 < m else float("inf")
        left2 = arr2[cut2 - 1] if cut2 > 0 else float("-inf")
        right2 = arr2[cut2] if cut2 < k else float("inf")

        if left1 <= right2 and left2 <= right1:
            if (m + k) % 2:
                return float(max(left1, left2))
            return (max(left1, left2) + min(right1, right2)) / 2.0

        if left1 > right2:
            high = cut1 - 1
        else:
            low = cut1 + 1

    raise ValueError("Input lists are not sorted")

