def heap_sort(arr):
    """Sort a list in ascending order using the heap sort algorithm."""
    a = list(arr)
    n = len(a)

    def sift_down(start, end):
        root = start
        while 2 * root + 1 <= end:
            child = 2 * root + 1
            if child + 1 <= end and a[child] < a[child + 1]:
                child += 1
            if a[root] < a[child]:
                a[root], a[child] = a[child], a[root]
                root = child
            else:
                return

    # Build a max heap.
    for start in range((n - 2) // 2, -1, -1):
        sift_down(start, n - 1)

    # Repeatedly move the maximum element to the end.
    for end in range(n - 1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift_down(0, end - 1)

    return a

