def maxAverageOfPath(matrix):
    """Return the maximum average cost over all right/down paths.

    Every path from the top-left to the bottom-right visits exactly
    ``2 * n - 1`` cells, so maximizing the average is equivalent to
    maximizing the path sum.
    """
    n = len(matrix)
    if n == 0:
        return 0.0

    # dp[j] holds the maximum sum to reach column j in the current row.
    dp = [float("-inf")] * n
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[j] = matrix[i][j]
            elif i == 0:
                dp[j] = dp[j - 1] + matrix[i][j]
            elif j == 0:
                dp[j] = dp[j] + matrix[i][j]
            else:
                dp[j] = max(dp[j], dp[j - 1]) + matrix[i][j]

    return dp[-1] / (2 * n - 1)

