def find_first_occurrence(arr, target):
    """Return the index of the first occurrence of target in a sorted array.

    Returns -1 if target is not present.
    """
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == target:
            result = mid
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

