from collections import Counter


def get_pairs_count(numbers, target_sum):
    """Return the number of unordered pairs whose sum equals target_sum."""
    counts = Counter(numbers)
    pairs = 0

    for value, count in counts.items():
        complement = target_sum - value

        if complement not in counts:
            continue

        if value < complement:
            pairs += count * counts[complement]
        elif value == complement:
            pairs += count * (count - 1) // 2

    return pairs


