def sum_in_range(l: int, r: int) -> int:
    """Return the sum of all odd natural numbers in the inclusive range [l, r]."""
    if l > r:
        return 0

    # Natural numbers start at 1, so ignore any non-positive part of the range.
    first = max(l, 1)
    if first % 2 == 0:
        first += 1

    last = r if r % 2 != 0 else r - 1

    if first > last:
        return 0

    count = (last - first) // 2 + 1
    return count * (first + last) // 2

